// Port of gas/test/reconcile.test.ts, reshaped for the three-scope code register.
//
// Two populations of test live here and it matters which is which:
//
//   FIXTURE PARITY — test/fixtures/reconcile.json and tags_json.json are BYTE COPIES from
//   gas/, generated by the Python domain layer and pinned a second time by
//   brick/tests/test_ledger.py::test_matches_the_gas_reconcile_fixture. They are never
//   edited or regenerated here. reconcile.json is fed through a RENAME SHIM (below) that
//   maps gas/'s column names onto sheetsDb.ts's, and nothing else: the records, the ledger,
//   the options and every expected value go in verbatim.
//
//   HAND-WRITTEN — the behaviour this register adds and gas/ has no golden for: SAST's
//   birth date, the secrets twin fold, the validation axis, removed-vs-rotated, and the
//   per-scope column projections. Every number in these is either read off the fixture or
//   derived with the arithmetic written out in the test.

import { describe, expect, it } from "vitest";
import { findingKey } from "../src/domain/lifecycle";
import {
  emptyRiskSignals,
  foldSecretTwins,
  ownerPath,
  ownerProject,
  projectsJson,
  projectsListJson,
  reconcile,
  tagsJson,
} from "../src/domain/reconcile";
import type { LedgerRow } from "../src/domain/ledgerTypes";
import { expectParity, fixture } from "./helpers";

// --------------------------------------------------------------------------- #
//  tags_json parity
// --------------------------------------------------------------------------- #

describe("tagsJson (fixture parity)", () => {
  const { cases } = fixture("tags_json");
  cases.forEach((c: any, i: number) => {
    it(`case ${i}`, () => {
      expectParity(tagsJson(c.input), c.expected);
    });
  });
});

// --------------------------------------------------------------------------- #
//  reconcile.json parity, through the rename shim
// --------------------------------------------------------------------------- #

/**
 * gas/ column -> gas_devsecops column. The rename is the ONLY transformation the shim makes.
 * Source of truth for the right-hand side is TAB_HEADERS[TABS.ledger] in
 * src/server/sheetsDb.ts, mirrored as LEDGER_COLUMNS in src/domain/ledgerTypes.ts.
 */
const RENAMED: Record<string, string> = {
  vuln_key: "finding_key",
  cve: "identifier",
  asset_id: "repo_id",
  asset_name: "repo_name",
  cloud: "platform",
};

/**
 * THE FIXTURE FIELDS WITH NO COUNTERPART, listed rather than silently dropped.
 *
 * All three describe a CLOUD asset, and this register's asset is a repository. They are not
 * renames that were forgotten; there is no column on the devsecops ledger that means the
 * same thing, and inventing one would put a null in front of an analyst under a heading that
 * promises a value.
 */
const UNMAPPED: Record<string, string> = {
  // The devsecops asset is always a repository, so a per-row asset TYPE carries no
  // information — except REPOSITORY vs REPOSITORY_BRANCH, which is exactly what the `branch`
  // column encodes (see splitRepoBranch). Dropped, not renamed.
  asset_type: "the asset is always a repository; REPOSITORY vs REPOSITORY_BRANCH is `branch`",
  // wizQueries.ts: "subscriptionName is always null on a repository branch". The ownership
  // dimension in this register is the project hierarchy — owner_project / owner_path, from
  // projects[] — which Q_SCA/Q_SAST/Q_SECRETS all select and gas/'s query does not.
  subscription_name: "no cloud subscription on a repo; ownership is owner_project from projects[]",
  subscription_ext_id: "same — see owner_project / owner_path",
};

/** Everything else passes through under its own name. */
const PASSTHROUGH = [
  "severity", "first_seen", "last_seen", "status", "resolved_at", "resolution_src",
  "reopened_count", "first_scan_id", "last_scan_id", "tags_json",
];

describe("reconcile.json rename shim — the mapping itself", () => {
  const { scenarios } = fixture("reconcile");
  const seenFields = new Set<string>();
  for (const sc of scenarios) {
    for (const row of Object.values<any>(sc.expected.ledger)) {
      for (const k of Object.keys(row)) seenFields.add(k);
    }
    for (const row of Object.values<any>(sc.input.ledger)) {
      for (const k of Object.keys(row)) seenFields.add(k);
    }
  }

  it("every field the fixture carries is either renamed, passed through, or listed as unmapped", () => {
    const accounted = new Set([
      ...Object.keys(RENAMED),
      ...Object.keys(UNMAPPED),
      ...PASSTHROUGH,
    ]);
    const unaccounted = [...seenFields].filter((f) => !accounted.has(f)).sort();
    expect(unaccounted, "fixture fields with no shim entry").toEqual([]);
    // 18 fields: 5 renamed + 3 unmapped + 10 passed through.
    expect(seenFields.size).toBe(18);
    expect(Object.keys(RENAMED).length + Object.keys(UNMAPPED).length + PASSTHROUGH.length)
      .toBe(18);
  });
});

/**
 * gas/'s vulnKey falls back to a content hash ("h:<16 hex>") when a node carries no `id`.
 * findingKey deliberately does NOT port that fallback — src/domain/lifecycle.ts states the
 * reason: sca and sast nodes always carry a Wiz-assigned id, since Q_SCA and Q_SAST both
 * select it. The fixture's `first_scan` has exactly ONE id-less record.
 *
 * D9b task 3 (see test/lifecycle.test.ts's "refuses a node with no id" suite): findingKey now
 * THROWS on a missing/blank id rather than keying it as the EMPTY identity "sca:id:" — the
 * old behaviour here, which this file used to shim onto with `HASH_FALLBACK_KEY = "sca:id:"`.
 * That was a FINDING about the fixture, not a safe fallback to keep: a second id-less node in
 * the same scan would have collided into the same "sca:id:" ledger row, silently merging two
 * distinct findings. So rather than route this one record through findingKey's now-removed
 * empty-identity path, the shim gives it a SYNTHETIC id — deterministic, derived from the
 * fixture's own "h:<hash>" fallback key (gas/'s vulnKey content hash for this record, computed
 * from its OTHER fields and therefore stable regardless of what id it carries) — before
 * reconcile ever sees it, and maps the fixture's "h:<hash>" key onto that same synthetic
 * "sca:id:fixture-<hash>" identity everywhere the shim rewrites a key.
 */
const { scenarios } = fixture("reconcile");
const idLessRecords = scenarios
  .flatMap((sc: any) => sc.input.records)
  .filter((r: any) => !String(r.id ?? "").trim());

const FIXTURE_HASH_KEYS = new Set<string>();
for (const sc of scenarios) {
  for (const k of Object.keys(sc.expected.ledger)) if (k.startsWith("h:")) FIXTURE_HASH_KEYS.add(k);
  for (const k of Object.keys(sc.input.ledger)) if (k.startsWith("h:")) FIXTURE_HASH_KEYS.add(k);
}
const [ONLY_HASH_KEY] = [...FIXTURE_HASH_KEYS];
// "fixture-<hash>" per the D9b brief's own example (id: "fixture-b9db6107009435fc") — derived
// from the fixture's one observed "h:" key rather than hardcoded, so this still fails loudly
// (a mismatched idLessRecords.length below) if a future fixture regeneration changes the shape.
const SYNTHETIC_ID = "fixture-" + String(ONLY_HASH_KEY ?? "").slice("h:".length);
// Mutates the shared fixture record in place, once, at module load — before any scenario's
// reconcile() call can reach it. findingKey("sca", record) would otherwise throw on this
// record's blank id (see the block comment above).
if (idLessRecords.length === 1) (idLessRecords[0] as Record<string, unknown>).id = SYNTHETIC_ID;
const HASH_FALLBACK_KEY = findingKey("sca", { id: SYNTHETIC_ID });

const renameKey = (k: string): string => (k.startsWith("h:") ? HASH_FALLBACK_KEY : `sca:${k}`);

function shimRow(row: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { scope: "sca" };
  for (const [k, v] of Object.entries(row)) {
    if (k in UNMAPPED) continue;
    out[RENAMED[k] ?? k] = k === "vuln_key" ? renameKey(String(v)) : v;
  }
  return out;
}

function shimLedger(ledger: Record<string, any>): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [k, row] of Object.entries(ledger)) out[renameKey(k)] = shimRow(row);
  return out;
}

function shimObservations(obs: any[]): unknown[] {
  return obs.map((o) => ({
    scan_id: o.scan_id,
    finding_key: renameKey(o.vuln_key),
    present: o.present,
    severity: o.severity,
    status: o.status,
  }));
}

describe("reconcile (reconcile.json parity, scope sca)", () => {
  // FALSIFIED CLAIM, from before D9b task 3: "the hash-fallback collapse is unambiguous" —
  // that asserted `HASH_FALLBACK_KEY === "sca:id:"`, i.e. that it was SAFE for findingKey to
  // key an id-less node as the empty identity, because the fixture happens to carry only one
  // such record. It is not safe in general (a second id-less node in the same scan would have
  // collided into that same row), which is exactly why findingKey now throws instead. This
  // fixture's one id-less record no longer reaches that path at all: the shim above gives it a
  // synthetic id before reconcile ever sees it, so what this test can honestly pin is that the
  // synthetic id is exactly what it claims to be — derived from the fixture's own "h:" key.
  it("the fixture's one id-less record is given a synthetic id derived from its own fixture hash", () => {
    expect(idLessRecords.length).toBe(1);
    expect((idLessRecords[0] as Record<string, unknown>).id).toBe(SYNTHETIC_ID);
    expect(SYNTHETIC_ID).toBe("fixture-b9db6107009435fc");
    expect(HASH_FALLBACK_KEY).toBe("sca:id:fixture-b9db6107009435fc");
    expect([...FIXTURE_HASH_KEYS]).toEqual(["h:b9db6107009435fc"]);
  });

  for (const sc of scenarios) {
    it(sc.name, () => {
      const o = sc.input.options ?? {};
      const { ledger, observations, deltas } = reconcile(
        sc.input.records,
        shimLedger(sc.input.ledger) as unknown as Record<string, LedgerRow>,
        sc.input.scan_id,
        sc.input.scan_ts,
        sc.input.prev_scan_id,
        {
          scope: "sca",
          ...(o.disappearance_mode ? { disappearanceMode: o.disappearance_mode } : {}),
          ...(o.prev_scan_ts ? { prevScanTs: o.prev_scan_ts } : {}),
          ...(o.scanned_severities ? { scannedSeverities: o.scanned_severities } : {}),
          ...(o.prev_scan_id_by_severity
            ? { prevScanIdBySeverity: o.prev_scan_id_by_severity }
            : {}),
        },
      );
      expectParity(deltas, sc.expected.deltas);
      expectParity(ledger, shimLedger(sc.expected.ledger));
      expectParity(observations, shimObservations(sc.expected.observations));
    });
  }

  it("does not mutate its inputs", () => {
    const sc = scenarios[1];
    const shimmed = shimLedger(sc.input.ledger) as unknown as Record<string, LedgerRow>;
    const ledgerCopy = JSON.stringify(shimmed);
    const recordsCopy = JSON.stringify(sc.input.records);
    reconcile(sc.input.records, shimmed, sc.input.scan_id, sc.input.scan_ts, sc.input.prev_scan_id, {
      scope: "sca",
    });
    expectParity(JSON.parse(ledgerCopy), shimmed);
    expectParity(JSON.parse(recordsCopy), sc.input.records);
  });

  it("twinStats is zeroed on a non-secrets scope — there are no twins to fold", () => {
    const sc = scenarios[0];
    const { twinStats } = reconcile(sc.input.records, {}, sc.input.scan_id, sc.input.scan_ts, null, {
      scope: "sca",
    });
    expect(twinStats).toEqual({ keys: 0, folded: 0, medianGapDays: null });
  });
});

