const run = (
  scope: "sca" | "sast" | "secrets",
  records: Record<string, unknown>[],
  ledger: Record<string, LedgerRow>,
  scanId: string,
  prevScanId: string | null = null,
  extra: Record<string, unknown> = {},
) => reconcile(records, ledger, scanId, scanId, prevScanId, { scope, ...extra } as any);

// --------------------------------------------------------------------------- #
//  Rule 1 / rule 2: scope, keys and the per-scope column projection
// --------------------------------------------------------------------------- #

describe("scope is part of the key and is stamped on the row", () => {
  it("keys come from findingKey(scope, node), so the same id in two scopes is two findings", () => {
    const sca = run("sca", [scaNode({ id: "shared" })], {}, S1);
    const sast = run("sast", [sastNode({ id: "shared" })], {}, S1);
    expect(Object.keys(sca.ledger)).toEqual(["sca:id:shared"]);
    expect(Object.keys(sast.ledger)).toEqual(["sast:id:shared"]);
    expect(sca.ledger["sca:id:shared"].scope).toBe("sca");
    expect(sast.ledger["sast:id:shared"].scope).toBe("sast");
  });

  it("a stored row that predates the scope column is re-stamped rather than left blank", () => {
    const stored = {
      "sca:id:sca-1": {
        finding_key: "sca:id:sca-1", severity: "HIGH", status: "OPEN",
        first_seen: "2026-03-01T00:00:00Z", last_seen: S1, last_scan_id: "s0",
        reopened_count: 0,
      },
    } as unknown as Record<string, LedgerRow>;
    const { ledger } = run("sca", [scaNode()], stored, S2);
    expect(ledger["sca:id:sca-1"].scope).toBe("sca");
  });
});

describe("per-scope column projection (rule 2)", () => {
  it("sca: identifier <- name, component <- detailedName, repo/branch/platform, language", () => {
    const row = run("sca", [scaNode()], {}, S1).ledger["sca:id:sca-1"];
    expect(row.identifier).toBe("CVE-2026-1");
    expect(row.component).toBe("braces");
    expect(row.repo_id).toBe("repo-1");
    expect(row.repo_name).toBe("dktunited/retbox-front");
    expect(row.branch).toBe("main");
    expect(row.platform).toBe("GitHub");
    expect(row.language).toBe("JAVASCRIPT");
    // The SAST/secrets columns stay null on an SCA row.
    expect(row.cwe).toBeNull();
    expect(row.file_path).toBeNull();
    expect(row.secret_kind).toBeNull();
    expect(row.validation_state).toBeNull();
  });

  it("sast: identifier <- name, cwe <- weaknesses[].id, file_path/start_line, ai_verdict, origin", () => {
    const row = run("sast", [sastNode()], {}, S1).ledger["sast:id:sast-1"];
    expect(row.identifier).toBe("Unsafe XML Processing with XMLInputFactory in Java");
    expect(row.cwe).toBe("CWE-611");
    expect(row.ai_verdict).toBe("NON_EXPLOITABLE");
    expect(row.language).toBe("JAVA");
    expect(row.file_path).toBe("tattoo/src/com/decathlon/Bo.java");
    expect(row.start_line).toBe(133);
    expect(row.origin).toBe("WIZ");
    expect(row.repo_name).toBe("dktunited/tattoo");
    expect(row.branch).toBe("stab");
    // Q_SAST's `resource { id name type }` selects no cloudPlatform — an honest gap.
    expect(row.platform).toBeNull();
  });

  it("cwe joins several weaknesses with ',' in a stable (sorted) order", () => {
    const row = run(
      "sast",
      [sastNode({ weaknesses: [{ id: "CWE-89" }, { id: "CWE-20" }, { id: "CWE-611" }] })],
      {},
      S1,
    ).ledger["sast:id:sast-1"];
    expect(row.cwe).toBe("CWE-20,CWE-611,CWE-89");
  });

  it("no weaknesses leaves cwe NULL, not '' — an absent weakness is unclassified, not low risk", () => {
    expect(run("sast", [sastNode({ weaknesses: [] })], {}, S1).ledger["sast:id:sast-1"].cwe)
      .toBeNull();
    expect(run("sast", [sastNode({ weaknesses: null })], {}, S1).ledger["sast:id:sast-1"].cwe)
      .toBeNull();
  });

  it("sast severity falls back to originalSeverity when Wiz reports none", () => {
    const row = run(
      "sast",
      [sastNode({ severity: null, originalSeverity: "CRITICAL" })],
      {},
      S1,
    ).ledger["sast:id:sast-1"];
    expect(row.severity).toBe("CRITICAL");
  });

  it("secrets: identifier <- secretDataId, secret_kind <- type, file_path <- path, start_line <- lineNumber", () => {
    const node = secretNode();
    const key = findingKey("secrets", node);
    const row = run("secrets", [node], {}, S1).ledger[key];
    expect(row.identifier).toBe("0dd42a12-52f3-50e1-9b3f-c3053ca9d45d");
    expect(row.secret_kind).toBe("SAAS_API_KEY");
    expect(row.confidence).toBe("High");
    expect(row.file_path).toBe("/resources/prod.txt");
    expect(row.start_line).toBe(6);
    expect(row.repo_name).toBe("dktunited/kconnect");
    expect(row.branch).toBeNull(); // resource.type REPOSITORY carries no branch
    expect(row.platform).toBe("GitHub");
    expect(row.validation_state).toBe("UNKNOWN");
  });

  it("component is NULL for sast and secrets — the located artefact lives in file_path", () => {
    expect(run("sast", [sastNode()], {}, S1).ledger["sast:id:sast-1"].component).toBeNull();
    const node = secretNode();
    expect(run("secrets", [node], {}, S1).ledger[findingKey("secrets", node)].component).toBeNull();
  });
});

describe("ownership from projects[] (all three scopes)", () => {
  // The live probe sample's shape: folders and leaves interleaved, no parent links.
  const projects = [
    { id: "p1", name: "VALUE-CHAIN", isFolder: true, slug: "value-chain" },
    { id: "p2", name: "product-TATTOO-idp", isFolder: false, slug: "product-tattoo-idp" },
    { id: "p3", name: "CE-TRANSPORT", isFolder: true, slug: "ce-transport" },
    { id: "p4", name: "GITHUB-DKTUNITED", isFolder: false, slug: "github-dktunited" },
  ];

  it("owner_project is the first leaf; owner_path is the folders, sorted", () => {
    expect(ownerProject({ projects })).toBe("product-TATTOO-idp");
    expect(ownerPath({ projects })).toBe("CE-TRANSPORT / VALUE-CHAIN");
  });

  it("tags_json renders projects[] as canonical sorted-key JSON keyed on slug", () => {
    expect(projectsJson({ projects })).toBe(
      '{"ce-transport": "CE-TRANSPORT", "github-dktunited": "GITHUB-DKTUNITED", ' +
        '"product-tattoo-idp": "product-TATTOO-idp", "value-chain": "VALUE-CHAIN"}',
    );
  });

  it("a node with no projects leaves all three null", () => {
    const row = run("sast", [sastNode()], {}, S1).ledger["sast:id:sast-1"];
    expect(row.owner_project).toBeNull();
    expect(row.owner_path).toBeNull();
    expect(row.tags_json).toBeNull();
  });

  it("the ledger row carries them", () => {
    const row = run("sast", [sastNode({ projects })], {}, S1).ledger["sast:id:sast-1"];
    expect(row.owner_project).toBe("product-TATTOO-idp");
    expect(row.owner_path).toBe("CE-TRANSPORT / VALUE-CHAIN");
    expect(row.tags_json).toContain('"value-chain": "VALUE-CHAIN"');
  });
});

// --------------------------------------------------------------------------- #
//  projectsListJson (P1: the flat projects[] list, uncollapsed) — additive alongside
//  projectsJson, which stays byte-identical (test/reconcile.test.ts:441-ish above).
// --------------------------------------------------------------------------- #

describe("projectsListJson — the flat projects[] list, additive alongside projectsJson", () => {
  const projects = [
    { id: "p1", name: "VALUE-CHAIN", isFolder: true, slug: "value-chain" },
    { id: "p2", name: "product-TATTOO-idp", isFolder: false, slug: "product-tattoo-idp" },
    { id: "p3", name: "CE-TRANSPORT", isFolder: true, slug: "ce-transport" },
    { id: "p4", name: "GITHUB-DKTUNITED", isFolder: false, slug: "github-dktunited" },
  ];

  it("renders [{slug, name, isFolder}], sorted by slug, through the SAME canonical writer", () => {
    expect(projectsListJson({ projects })).toBe(
      '[{"isFolder": true, "name": "CE-TRANSPORT", "slug": "ce-transport"}, ' +
        '{"isFolder": false, "name": "GITHUB-DKTUNITED", "slug": "github-dktunited"}, ' +
        '{"isFolder": false, "name": "product-TATTOO-idp", "slug": "product-tattoo-idp"}, ' +
        '{"isFolder": true, "name": "VALUE-CHAIN", "slug": "value-chain"}]',
    );
  });

  it("projectsJson's own output is UNCHANGED on the same input — side by side", () => {
    const record = { projects };
    // projectsJson still collapses to {slug: name}; projectsListJson is the new, additive,
    // uncollapsed sibling. Asserted together so a future edit to one cannot silently start
    // moving the other's pinned bytes (test/reconcile.test.ts's original assertion at line
    // ~441 already pins projectsJson alone; this is the side-by-side the package asked for).
    expect(projectsJson(record)).toBe(
      '{"ce-transport": "CE-TRANSPORT", "github-dktunited": "GITHUB-DKTUNITED", ' +
        '"product-tattoo-idp": "product-TATTOO-idp", "value-chain": "VALUE-CHAIN"}',
    );
    expect(projectsListJson(record)).not.toBe(projectsJson(record));
  });

  it("isFolder is TRI-STATE: omitted entirely when the API did not report it, never false", () => {
    const noFlag = [{ slug: "no-flag", name: "No Flag" }];
    const rendered = projectsListJson({ projects: noFlag });
    expect(rendered).toBe('[{"name": "No Flag", "slug": "no-flag"}]');
    expect(rendered).not.toContain("isFolder");
    // And round-trips through JSON.parse as a key genuinely absent, not `false`.
    const parsed = JSON.parse(rendered!);
    expect("isFolder" in parsed[0]).toBe(false);
  });

  it("keys on slug, falling back to id, matching projectsJson's rule", () => {
    const noSlug = [{ id: "p-only-id", name: "Only Id", isFolder: false }];
    expect(projectsListJson({ projects: noSlug })).toBe(
      '[{"isFolder": false, "name": "Only Id", "slug": "p-only-id"}]',
    );
  });

  it("a record with no projects at all returns null, same convention as projectsJson", () => {
    expect(projectsListJson({})).toBeNull();
    expect(projectsListJson({ projects: [] })).toBeNull();
  });

  it("the ledger row carries it, additively — tags_json/owner_project are untouched", () => {
    const row = run("sast", [sastNode({ projects })], {}, S1).ledger["sast:id:sast-1"];
    expect(row.projects_json).toContain('"slug": "value-chain"');
    expect(row.projects_json).toContain('"isFolder": true');
    expect(row.owner_project).toBe("product-TATTOO-idp");
    expect(row.tags_json).toContain('"value-chain": "VALUE-CHAIN"');
  });

  it("a node with no projects leaves projects_json null too", () => {
    const row = run("sast", [sastNode()], {}, S1).ledger["sast:id:sast-1"];
    expect(row.projects_json).toBeNull();
  });

  it("latest-wins-never-erased: a later scan with no projects[] does not blank the column", () => {
    const s1 = run("sast", [sastNode({ projects })], {}, S1);
    const s2 = run("sast", [sastNode({ projects: undefined })], s1.ledger, S2);
    expect(s2.ledger["sast:id:sast-1"].projects_json).toBe(s1.ledger["sast:id:sast-1"].projects_json);
  });
});

// --------------------------------------------------------------------------- #
//  Rule 3: the birth date, and SAST's in particular
// --------------------------------------------------------------------------- #

describe("apiFirst = firstDetectedAt ?? firstSeenAt ?? createdAt (rule 3)", () => {
  it("SAST's birth date is createdAt", () => {
    const row = run("sast", [sastNode()], {}, S1).ledger["sast:id:sast-1"];
    expect(row.first_seen).toBe("2026-03-01T00:00:00Z");
  });

  it("secrets' birth date is firstSeenAt", () => {
    const node = secretNode({ firstSeenAt: "2026-02-14T06:00:00Z" });
    const row = run("secrets", [node], {}, S1).ledger[findingKey("secrets", node)];
    expect(row.first_seen).toBe("2026-02-14T06:00:00Z");
  });

  it("firstDetectedAt wins over both when present", () => {
    const row = run(
      "sast",
      [sastNode({ firstDetectedAt: "2026-01-05T00:00:00Z", createdAt: "2026-03-01T00:00:00Z" })],
      {},
      S1,
    ).ledger["sast:id:sast-1"];
    expect(row.first_seen).toBe("2026-01-05T00:00:00Z");
  });

  it("a node with no birth date at all falls back to the scan ts, never to null", () => {
    const row = run("sast", [sastNode({ createdAt: null })], {}, S1).ledger["sast:id:sast-1"];
    expect(row.first_seen).toBe(S1);
  });

  it("SAST resolves by DISAPPEARANCE and gets a real MTTR from its own two dates", () => {
    // Scan 1 sees it (createdAt 2026-03-01); scan 2 does not.
    const s1 = run("sast", [sastNode()], {}, S1);
    expect(s1.ledger["sast:id:sast-1"].status).toBe("OPEN");

    const s2 = run("sast", [], s1.ledger, S2, S1);
    const row = s2.ledger["sast:id:sast-1"];
    expect(row.status).toBe("RESOLVED");
    expect(row.resolution_src).toBe("disappeared");
    expect(row.resolved_at).toBe(S2);
    expect(row.first_seen).toBe("2026-03-01T00:00:00Z");
    // Arithmetic, by hand: 2026-03-17T00:00:00Z - 2026-03-01T00:00:00Z
    //   = 16 whole days (March 1 -> March 17), 16 * 86_400_000 ms.
    const mttrMs = Date.parse(row.resolved_at!) - Date.parse(row.first_seen!);
    expect(mttrMs).toBe(16 * 86_400_000);
    expect(mttrMs).toBeGreaterThan(0);
    expect(s2.deltas.resolved_count).toBe(1);
  });
});

// --------------------------------------------------------------------------- #
//  Rule 5: the secrets twin fold
// --------------------------------------------------------------------------- #

describe("secrets twin fold (rule 5)", () => {
  // ONE credential, ONE file, ONE line — recorded by Wiz twice, against the REPOSITORY
  // resource and against REPOSITORY_BRANCH, with different id, different externalId and
  // different birth dates. PROBE_FINDINGS.md §10.6/§10.7.
  const repositoryTwin = secretNode({
    id: "sec-repo",
    externalId: "github.com##dktunited/kconnect##/resources/prod.txt##abc##4",
    firstSeenAt: "2026-05-20T00:00:00Z",
    lastSeenAt: "2026-06-01T00:00:00Z", // the FRESHER of the two
    validationStatus: "VALID",
    lastValidatedAt: "2026-05-31T00:00:00Z",
    resource: {
      id: "res-repo", name: "dktunited/kconnect", type: "REPOSITORY", cloudPlatform: "GitHub",
    },
  });
  const branchTwin = secretNode({
    id: "sec-branch",
    externalId: "github.com##dktunited/kconnect##main##/resources/prod.txt##abc##4",
    firstSeenAt: "2026-04-30T12:00:00Z", // the EARLIER of the two
    lastSeenAt: "2026-05-25T00:00:00Z",
    validationStatus: "UNKNOWN",
    lastValidatedAt: null,
    resource: {
      id: "res-branch", name: "dktunited/kconnect/main", type: "REPOSITORY_BRANCH",
      cloudPlatform: "GitHub",
    },
  });

  it("the two twins already share a finding_key but differ on id and externalId", () => {
    expect(findingKey("secrets", repositoryTwin)).toBe(findingKey("secrets", branchTwin));
    expect(repositoryTwin.id).not.toBe(branchTwin.id);
    expect(repositoryTwin.externalId).not.toBe(branchTwin.externalId);
  });

  it("folds to ONE row: earliest first_seen, branch from the branch twin, status from the fresher twin", () => {
    const key = findingKey("secrets", repositoryTwin);
    const { ledger, deltas, twinStats } = run(
      "secrets",
      [repositoryTwin, branchTwin],
      {},
      "2026-06-05T00:00:00Z",
    );

    expect(Object.keys(ledger)).toEqual([key]);
    expect(deltas.new_count).toBe(1);

    const row = ledger[key];
    // Earliest firstSeenAt across the twins — the branch twin's here.
    expect(row.first_seen).toBe("2026-04-30T12:00:00Z");
    // resource / branch from the REPOSITORY_BRANCH twin, even though it is the STALER one.
    expect(row.repo_id).toBe("res-branch");
    expect(row.repo_name).toBe("dktunited/kconnect");
    expect(row.branch).toBe("main");
    // validationStatus from the twin with the LATER lastSeenAt — the repository twin here,
    // which is the one carrying the measured VALID.
    expect(row.validation_state).toBe("VALID");
    expect(row.validated_at).toBe("2026-05-31T00:00:00Z");

    // THE ARITHMETIC, by hand:
    //   branch twin firstSeenAt  2026-04-30T12:00:00Z
    //   repo   twin firstSeenAt  2026-05-20T00:00:00Z
    //   Apr 30 12:00 -> May  1 00:00 =  0.5 d
    //   May  1 00:00 -> May 20 00:00 = 19.0 d
    //                             gap = 19.5 d, and the median of one value is that value.
    // (The measured tenant-wide median is 19.9 d — §10.7 — which is why this is the shape of
    // the fixture rather than a round number.)
    expect(twinStats).toEqual({ keys: 1, folded: 1, medianGapDays: 19.5 });
    const gapMs = Date.parse("2026-05-20T00:00:00Z") - Date.parse("2026-04-30T12:00:00Z");
    expect(gapMs / 86_400_000).toBe(19.5);
  });

  it("keying on externalId instead would DOUBLE the ledger — the defect the fold exists to stop", () => {
    // Same two nodes, keyed the way §9.5 recommended and §10.6 falsified.
    const byExternalId = new Set([repositoryTwin.externalId, branchTwin.externalId]);
    expect(byExternalId.size).toBe(2);
    const { ledger } = run("secrets", [repositoryTwin, branchTwin], {}, "2026-06-05T00:00:00Z");
    expect(Object.keys(ledger).length).toBe(1);
  });

  it("a single untwinned node folds to itself and reports no twins", () => {
    const node = secretNode();
    const { ledger, twinStats } = run("secrets", [node], {}, S1);
    expect(Object.keys(ledger)).toEqual([findingKey("secrets", node)]);
    expect(twinStats).toEqual({ keys: 0, folded: 0, medianGapDays: null });
  });

  it("foldSecretTwins counts keys and folded nodes independently", () => {
    // Two twins of one credential (2 nodes -> 1) plus a triple of another (3 nodes -> 1),
    // plus one untwinned node. keys = 2, folded = (2-1) + (3-1) = 3.
    const other = (over: Record<string, unknown>) =>
      secretNode({ secretDataId: "other-credential", path: "/b.txt", lineNumber: 9, ...over });
    const { nodes, stats } = foldSecretTwins([
      repositoryTwin,
      branchTwin,
      other({ id: "o1", firstSeenAt: "2026-01-01T00:00:00Z", lastSeenAt: "2026-02-01T00:00:00Z" }),
      other({ id: "o2", firstSeenAt: "2026-01-11T00:00:00Z", lastSeenAt: "2026-02-02T00:00:00Z" }),
      other({ id: "o3", firstSeenAt: "2026-01-21T00:00:00Z", lastSeenAt: "2026-02-03T00:00:00Z" }),
      secretNode({ id: "lone", secretDataId: "third", path: "/c.txt", lineNumber: 1 }),
    ]);
    expect(nodes.length).toBe(3);
    expect(stats.keys).toBe(2);
    expect(stats.folded).toBe(3);
    // Gaps, by hand: twin pair 19.5 d (above); the triple spans 2026-01-01 -> 2026-01-21 =
    // 20 d. Median of [19.5, 20] = (19.5 + 20) / 2 = 19.75.
    expect(stats.medianGapDays).toBe(19.75);
  });
});

