describe("update disciplines (rule 6)", () => {
  it("latest-wins: severity and identifier follow the newest observation", () => {
    const s1 = run("sca", [scaNode({ severity: "HIGH" })], {}, S1);
    const s2 = run("sca", [scaNode({ severity: "CRITICAL", name: "CVE-2026-9" })], s1.ledger, S2);
    expect(s2.ledger["sca:id:sca-1"].severity).toBe("CRITICAL");
    expect(s2.ledger["sca:id:sca-1"].identifier).toBe("CVE-2026-9");
  });

  it("latest-wins-NEVER-ERASED: a scan that omits an attribute does not wipe it", () => {
    const s1 = run("sca", [scaNode({ fixedVersion: "3.0.3" })], {}, S1);
    expect(s1.ledger["sca:id:sca-1"].repo_name).toBe("dktunited/retbox-front");
    expect(s1.ledger["sca:id:sca-1"].fixed_version).toBe("3.0.3");

    const s2 = run(
      "sca",
      [{ id: "sca-1", name: "CVE-2026-1", severity: "HIGH", status: "OPEN" }],
      s1.ledger,
      S2,
    );
    const row = s2.ledger["sca:id:sca-1"];
    expect(row.repo_name).toBe("dktunited/retbox-front");
    expect(row.repo_id).toBe("repo-1");
    expect(row.branch).toBe("main");
    expect(row.platform).toBe("GitHub");
    expect(row.language).toBe("JAVASCRIPT");
    expect(row.fixed_version).toBe("3.0.3");
  });

  it("sticky first-wins, reset by reopen: the vendor-fix clock", () => {
    const s1 = run("sca", [scaNode({ fixedVersion: null, fixDate: null })], {}, S1);
    expect(s1.ledger["sca:id:sca-1"].fix_observed_at).toBeNull();

    const s2 = run(
      "sca",
      [scaNode({ fixedVersion: "1.2.3", fixDate: "2026-03-15T00:00:00Z" })],
      s1.ledger,
      S2,
    );
    expect(s2.ledger["sca:id:sca-1"].fix_observed_at).toBe(S2);
    expect(s2.ledger["sca:id:sca-1"].fix_date).toBe("2026-03-15T00:00:00Z");

    const s3 = run(
      "sca",
      [scaNode({ fixedVersion: "1.2.4", fixDate: "2026-03-20T00:00:00Z" })],
      s2.ledger,
      "2026-03-25T00:00:00Z",
    );
    expect(s3.ledger["sca:id:sca-1"].fix_observed_at).toBe(S2);
    expect(s3.ledger["sca:id:sca-1"].fix_date).toBe("2026-03-15T00:00:00Z");
  });

  it("tri-state risk signals: a record carrying no signal keys leaves all four NULL", () => {
    const row = run("sca", [scaNode()], {}, S1).ledger["sca:id:sca-1"];
    expect(row.has_kev).toBeNull();
    expect(row.has_exploit).toBeNull();
    expect(row.epss).toBeNull();
    expect(row.risk_observed_at).toBeNull();
  });

  it("tri-state risk signals: an observed false is false — distinct from not-captured null", () => {
    const row = run(
      "sca",
      [scaNode({ hasCisaKevExploit: false, hasExploit: false, epssProbability: 0.02 })],
      {},
      S1,
    ).ledger["sca:id:sca-1"];
    expect(row.has_kev).toBe(false);
    expect(row.has_exploit).toBe(false);
    expect(row.epss).toBe(0.02);
    expect(row.risk_observed_at).toBe(S1);
  });

  it("monotone: false -> true sticks, and true never reverts; epss keeps the peak", () => {
    const s1 = run("sca", [scaNode({ hasExploit: false, epssProbability: 0.4 })], {}, S1);
    expect(s1.ledger["sca:id:sca-1"].has_exploit).toBe(false);

    const s2 = run("sca", [scaNode({ hasExploit: true, epssProbability: 0.82 })], s1.ledger, S2);
    expect(s2.ledger["sca:id:sca-1"].has_exploit).toBe(true);
    expect(s2.ledger["sca:id:sca-1"].epss).toBe(0.82);

    const s3 = run(
      "sca",
      [scaNode({ hasExploit: false, epssProbability: 0.05 })],
      s2.ledger,
      "2026-03-25T00:00:00Z",
    );
    expect(s3.ledger["sca:id:sca-1"].has_exploit).toBe(true);
    expect(s3.ledger["sca:id:sca-1"].epss).toBe(0.82);
    // risk_observed_at pins to the EARLIEST witnessing scan, in either replay order.
    expect(s3.ledger["sca:id:sca-1"].risk_observed_at).toBe(S1);
  });

  it("a reopen resets the fix clock but NOT the risk signals", () => {
    const resolved: Record<string, LedgerRow> = {
      "sca:id:sca-1": {
        finding_key: "sca:id:sca-1", scope: "sca", identifier: "CVE-2026-1", component: "braces",
        severity: "HIGH", repo_id: "repo-1", repo_name: "dktunited/retbox-front",
        branch: "main", platform: "GitHub", first_seen: "2026-03-01T00:00:00Z", last_seen: S1,
        status: "RESOLVED", resolved_at: S1, resolution_src: "api", reopened_count: 0,
        first_scan_id: "s0", last_scan_id: "s0", fix_date: "2026-02-20T00:00:00Z",
        fix_observed_at: S1, fixed_version: "1.2.3",
        has_kev: true, has_exploit: true, epss: 0.7, risk_observed_at: "2026-03-01T00:00:00Z",
        cwe: null, ai_verdict: null, language: "JAVASCRIPT", file_path: null, start_line: null,
        origin: null, secret_kind: null, rotated_at: null, removed_at: null,
        validation_state: null, validated_at: null, confidence: null,
        owner_project: null, owner_path: null, tags_json: null, projects_json: null,
      },
    };
    const { ledger, deltas } = run("sca", [scaNode()], resolved, S2);
    const row = ledger["sca:id:sca-1"];
    expect(deltas.reopened_count).toBe(1);
    expect(row.reopened_count).toBe(1);
    expect(row.status).toBe("OPEN");
    expect(row.fix_date).toBeNull(); // per-episode: cleared
    expect(row.fix_observed_at).toBeNull();
    expect(row.has_kev).toBe(true); // per-vulnerability: kept
    expect(row.has_exploit).toBe(true);
    expect(row.epss).toBe(0.7);
    expect(row.risk_observed_at).toBe("2026-03-01T00:00:00Z");
  });

  it("emptyRiskSignals is all-null, never false or 0", () => {
    expect(emptyRiskSignals()).toEqual({
      has_kev: null, has_exploit: null, epss: null, risk_observed_at: null,
    });
  });
});

