//  Rule 7: the secrets validation axis
// --------------------------------------------------------------------------- #

describe("validation is latest-wins among MEASURED states only (rule 7)", () => {
  const node = secretNode();
  const key = findingKey("secrets", node);

  it("UNKNOWN does not overwrite VALID — 99.6% of this tenant's instances read UNKNOWN", () => {
    const s1 = run(
      "secrets",
      [secretNode({ validationStatus: "VALID", lastValidatedAt: "2026-03-05T00:00:00Z" })],
      {},
      S1,
    );
    expect(s1.ledger[key].validation_state).toBe("VALID");
    expect(s1.ledger[key].validated_at).toBe("2026-03-05T00:00:00Z");

    const s2 = run(
      "secrets",
      [secretNode({ validationStatus: "UNKNOWN", lastValidatedAt: null })],
      s1.ledger,
      S2,
    );
    expect(s2.ledger[key].validation_state).toBe("VALID");
    expect(s2.ledger[key].validated_at).toBe("2026-03-05T00:00:00Z");
  });

  it("ERROR does not overwrite INVALID either", () => {
    const s1 = run(
      "secrets",
      [secretNode({ validationStatus: "INVALID", lastValidatedAt: "2026-03-05T00:00:00Z" })],
      {},
      S1,
    );
    const s2 = run("secrets", [secretNode({ validationStatus: "ERROR" })], s1.ledger, S2);
    expect(s2.ledger[key].validation_state).toBe("INVALID");
  });

  it("an unmeasured state may still FILL a null column — looked-and-got-UNKNOWN is not never-looked", () => {
    expect(run("secrets", [node], {}, S1).ledger[key].validation_state).toBe("UNKNOWN");
  });

  it("a measured state DOES overwrite a measured one: VALID -> INVALID", () => {
    const s1 = run(
      "secrets",
      [secretNode({ validationStatus: "VALID", lastValidatedAt: "2026-03-05T00:00:00Z" })],
      {},
      S1,
    );
    const s2 = run(
      "secrets",
      [secretNode({ validationStatus: "INVALID", lastValidatedAt: "2026-03-16T00:00:00Z" })],
      s1.ledger,
      S2,
    );
    expect(s2.ledger[key].validation_state).toBe("INVALID");
    expect(s2.ledger[key].validated_at).toBe("2026-03-16T00:00:00Z");
  });

  it("rotated_at is set ONCE, from validated_at, on the first INVALID", () => {
    const s1 = run(
      "secrets",
      [secretNode({ validationStatus: "INVALID", lastValidatedAt: "2026-03-05T00:00:00Z" })],
      {},
      S1,
    );
    expect(s1.ledger[key].rotated_at).toBe("2026-03-05T00:00:00Z");

    // A second INVALID with a LATER validated_at moves validated_at and not rotated_at.
    const s2 = run(
      "secrets",
      [secretNode({ validationStatus: "INVALID", lastValidatedAt: "2026-03-16T00:00:00Z" })],
      s1.ledger,
      S2,
    );
    expect(s2.ledger[key].validated_at).toBe("2026-03-16T00:00:00Z");
    expect(s2.ledger[key].rotated_at).toBe("2026-03-05T00:00:00Z");
  });

  it("an INVALID with no lastValidatedAt dates rotation by OBSERVATION rather than dropping it", () => {
    const s1 = run(
      "secrets",
      [secretNode({ validationStatus: "INVALID", lastValidatedAt: null })],
      {},
      S1,
    );
    expect(s1.ledger[key].validated_at).toBeNull();
    expect(s1.ledger[key].rotated_at).toBe(S1);
  });

  it("an UNKNOWN row is not rotated — absent is never zero", () => {
    expect(run("secrets", [node], {}, S1).ledger[key].rotated_at).toBeNull();
  });

  it("a reopen clears removed_at and rotated_at but KEEPS validation_state", () => {
    const resolved: Record<string, LedgerRow> = {
      [key]: {
        finding_key: key, scope: "secrets",
        identifier: "0dd42a12-52f3-50e1-9b3f-c3053ca9d45d", component: null, severity: "HIGH",
        repo_id: "res-1", repo_name: "dktunited/kconnect", branch: null, platform: "GitHub",
        first_seen: "2026-03-01T00:00:00Z", last_seen: S1, status: "RESOLVED",
        resolved_at: S1, resolution_src: "disappeared", reopened_count: 0,
        first_scan_id: "s0", last_scan_id: "s0",
        fix_date: null, fix_observed_at: null, fixed_version: null,
        has_kev: null, has_exploit: null, epss: null, risk_observed_at: null,
        cwe: null, ai_verdict: null, language: null,
        file_path: "/resources/prod.txt", start_line: 6, origin: null,
        secret_kind: "SAAS_API_KEY",
        rotated_at: "2026-03-05T00:00:00Z", removed_at: S1,
        validation_state: "INVALID", validated_at: "2026-03-05T00:00:00Z",
        confidence: "High", owner_project: null, owner_path: null, tags_json: null,
        projects_json: null,
      },
    };
    // The string is back in HEAD; nobody re-checked the credential (UNKNOWN).
    const { ledger, deltas } = run(
      "secrets",
      [secretNode({ validationStatus: "UNKNOWN", lastValidatedAt: null })],
      resolved,
      S2,
    );
    const row = ledger[key];
    expect(deltas.reopened_count).toBe(1);
    expect(row.status).toBe("OPEN");
    expect(row.removed_at).toBeNull();
    expect(row.rotated_at).toBeNull();
    // The last measurement anyone made of the credential survives the reopen.
    expect(row.validation_state).toBe("INVALID");
    expect(row.validated_at).toBe("2026-03-05T00:00:00Z");
  });
});

// --------------------------------------------------------------------------- #
//  Rule 8: disappearance, and removed-is-not-rotated
// --------------------------------------------------------------------------- #

describe("disappearance (rule 8)", () => {
  it("a secrets row that disappears sets removed_at = resolved_at and leaves rotated_at null", () => {
    const node = secretNode();
    const key = findingKey("secrets", node);
    const s1 = run("secrets", [node], {}, S1);
    const s2 = run("secrets", [], s1.ledger, S2, S1);
    const row = s2.ledger[key];
    expect(row.status).toBe("RESOLVED");
    expect(row.resolution_src).toBe("disappeared");
    expect(row.resolved_at).toBe(S2);
    expect(row.removed_at).toBe(S2);
    // REMOVED IS NOT ROTATED: the string left HEAD; the credential is live until measured dead.
    expect(row.rotated_at).toBeNull();
    expect(row.validation_state).toBe("UNKNOWN");
    expect(s2.observations).toEqual([
      { scan_id: S2, finding_key: key, present: 0, severity: "HIGH", status: "RESOLVED" },
    ]);
  });

  it("an API-declared resolution on secrets is also a removal (PROBE_FINDINGS.md §3)", () => {
    const node = secretNode({ status: "RESOLVED", resolvedAt: "2026-03-09T12:00:00Z" });
    const key = findingKey("secrets", node);
    const row = run("secrets", [node], {}, S1).ledger[key];
    expect(row.resolution_src).toBe("api");
    expect(row.resolved_at).toBe("2026-03-09T12:00:00Z");
    expect(row.removed_at).toBe("2026-03-09T12:00:00Z");
    expect(row.rotated_at).toBeNull();
  });

  it("the midpoint mode dates the resolution halfway between the two scans", () => {
    const s1 = run("sast", [sastNode()], {}, S1);
    const s2 = run("sast", [], s1.ledger, S2, S1, {
      disappearanceMode: "midpoint",
      prevScanTs: S1,
    });
    // 2026-03-10T00:00:00Z .. 2026-03-17T00:00:00Z is 7 days; the midpoint is +3.5 d,
    // i.e. 2026-03-13T12:00:00Z.
    expect(s2.ledger["sast:id:sast-1"].resolved_at).toBe("2026-03-13T12:00:00Z");
  });

  it("a row last seen before the previous scan is not re-resolved", () => {
    const stale = {
      "sast:id:sast-1": {
        finding_key: "sast:id:sast-1", scope: "sast", severity: "HIGH", status: "OPEN",
        first_seen: "2026-03-01T00:00:00Z", last_seen: "2026-03-03T00:00:00Z",
        last_scan_id: "an-older-scan", reopened_count: 0,
      },
    } as unknown as Record<string, LedgerRow>;
    const { ledger, deltas } = run("sast", [], stale, S2, S1);
    expect(ledger["sast:id:sast-1"].status).toBe("OPEN");
    expect(deltas.resolved_count).toBe(0);
  });
});

// --------------------------------------------------------------------------- #
//  Rule 9: the severity-scope guard
// --------------------------------------------------------------------------- #

describe("severity-scope guard (rule 9)", () => {
  it("a MEDIUM row is untouched by a scan whose scannedSeverities is [CRITICAL, HIGH]", () => {
    const medium: LedgerRow = {
      finding_key: "sca:id:med-1", scope: "sca", identifier: "CVE-2026-MED", component: "lodash",
      severity: "MEDIUM", repo_id: "repo-2", repo_name: "dktunited/other", branch: "main",
      platform: "GitHub", first_seen: "2026-02-01T00:00:00Z", last_seen: S1, status: "OPEN",
      resolved_at: null, resolution_src: null, reopened_count: 0,
      first_scan_id: S1, last_scan_id: S1,
      fix_date: null, fix_observed_at: null, fixed_version: null,
      has_kev: null, has_exploit: null, epss: null, risk_observed_at: null,
      cwe: null, ai_verdict: null, language: null, file_path: null, start_line: null,
      origin: null, secret_kind: null, rotated_at: null, removed_at: null,
      validation_state: null, validated_at: null, confidence: null,
      owner_project: null, owner_path: null, tags_json: null, projects_json: null,
    };
    const before = JSON.stringify(medium);

    // A CRITICAL/HIGH-scoped scan that sees a different finding entirely. Without the guard
    // the MEDIUM row would "disappear" and mass-resolve — absence of something nobody looked
    // for is not evidence.
    const { ledger, deltas } = run(
      "sca",
      [scaNode()],
      { "sca:id:med-1": medium },
      S2,
      S1,
      { scannedSeverities: ["CRITICAL", "HIGH"] },
    );
    expect(JSON.stringify(ledger["sca:id:med-1"])).toBe(before);
    expect(deltas.resolved_count).toBe(0);

    // …and the same scan WITHOUT the scope does resolve it, which is what makes the guard
    // the cause rather than a coincidence.
    const unscoped = run("sca", [scaNode()], { "sca:id:med-1": medium }, S2, S1);
    expect(unscoped.ledger["sca:id:med-1"].status).toBe("RESOLVED");
    expect(unscoped.deltas.resolved_count).toBe(1);
  });
});
